head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf70010";
scwin.editor = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"authYn":"Y"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ldMktTpCd, pageContext.psDepCd, pageContext.usrTpCd, integSrchNo

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2'); } }, { id: "if_ldMktTpCd_4", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_5", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_ldMktTpCd_6", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '6' || (dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "btn_regIntegSrchNm", fn: function(){ return ((dma_pageContext.get("integSrchNo") ?? "")===''); } }, { id: "c_otherwise_87", fn: function(){ return (!(((dma_pageContext.get("integSrchNo") ?? "")===''))); } }, { id: "if_authYn", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }, { id: "if_authYn_3", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }, { id: "if_authYn_4", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }, { id: "if_authYn_5", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_integSrchNo", fn: function () { return String(String((dma_pageContext.get("integSrchNo") ?? ""))); } },
        { childId: "ipt_searchRelLawNm", fn: function () { return String(String((dma_pageContext.get("searchRelLawNm") ?? ""))); } },
        { childId: "ipt_searchRelLawNm2", fn: function () { return String(String((dma_pageContext.get("searchRelLawNm") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent('slc_chargInstId').setValue('' + dma_integSrchDetail.get("chrg_inst_id") + '');
        $c.util.getComponent('slc_ldMktTpCd').setValue('' + dma_integSrchDetail.get("ld_mkt_tp_cd") + '');
        $c.util.getComponent('slc_submitDeadlineId').setValue('' + dma_integSrchDetail.get("submit_deadline_id") + '');
        $c.util.getComponent('slc_disclsTpId').setValue('' + dma_integSrchDetail.get("discls_tp_id") + '');
        const formCd = $c.util.getComponent('ipt_formCd').getValue();
        if (formCd.length > 0) {
            // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
            setInputDisable($('#integSrchNm'));
            $c.util.getComponent("formSearchSpan").setDisabled(true);
        } else {
            $c.util.getComponent("input_44").setDisabled(true);
        }
        $c.util.getComponent("ipt_duplChk").setDisabled(true);
        scwin.tx_fn_searchKeywrdListDtl();
        // TODO Stage2(규칙 19): jQuery — 라디오/체크 그룹 → 퍼블리싱 그룹 컴포넌트 getValue/setValue
        const integDiv = $('input:radio[name="integDiv"]:checked').val();
        if (integDiv === '2') {
            // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
            setInputEnable($('#integSrchNm'));
            $c.util.getComponent("formSearchSpan").setDisabled(true);
            $c.util.getComponent('ipt_integSrchNmChck').setValue("N");
        }
        if (dma_hiddenStore.get("integSrchNm").length > 0) {
            $c.util.getComponent('ipt_integSrchNmChck').setValue("Y");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70010.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf70010' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf70010.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
