/**
 * @method
 * @name clickDiv
 * @description click Div 처리
 * @param {*} div div
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clickDiv = async function (div) {
    if (div === '1') {
        const integSrchNm = dma_hiddenStore.get("integSrchNm");
        if (integSrchNm.length > 0) {
            if (await $c.win.confirm("통합검색명을 삭제하시겠습니까?")) {
                ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('integSrchNm', "") : console.warn('[sdd] hiddenStore 부재: integSrchNm'));
                // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
                setInputDisable($('#integSrchNm'));
                $c.util.getComponent("ipt_duplChk").setDisabled(true);
                $c.util.getComponent("formSearchSpan").setDisabled(false);
            } else {
                // TODO Stage2(규칙 19): jQuery — 라디오/체크 그룹 → 퍼블리싱 그룹 컴포넌트 getValue/setValue
                $('input:radio[name="integDiv"][value="2"]').prop('checked', true);
            }
        } else {
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('integSrchNm', "") : console.warn('[sdd] hiddenStore 부재: integSrchNm'));
            // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
            setInputDisable($('#integSrchNm'));
            $c.util.getComponent("ipt_duplChk").setDisabled(true);
            $c.util.getComponent("formSearchSpan").setDisabled(false);
        }
    } else {
        if (div === '2') {
            if ($c.util.getComponent('ipt_formCd').getValue().length > 0) {
                const rtnVal = await scwin.delFormData();
                if ("cancel" === rtnVal) {
                    // TODO Stage2(규칙 19): jQuery — 라디오/체크 그룹 → 퍼블리싱 그룹 컴포넌트 getValue/setValue
                    $('input:radio[name="integDiv"][value="1"]').prop('checked', true);
                } else {
                    // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
                    setInputEnable($('#integSrchNm'));
                    $c.util.getComponent("formSearchSpan").setDisabled(true);
                    $c.util.getComponent('ipt_integSrchNmChck').setValue("N");
                }
            } else {
                // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
                setInputEnable($('#integSrchNm'));
                $c.util.getComponent("formSearchSpan").setDisabled(true);
                $c.util.getComponent('ipt_integSrchNmChck').setValue("N");
            }
        }
    }
};

